# Notes: Keeps the original question text and legacy fields.
# ------------------------------------------------------------
def assemble_lesson(student_id, objective, story_concept, questions, pacing):
    """Build a teacher-reviewable lesson using approved question text."""

    if not questions:
        raise ValueError("Cannot assemble a lesson without questions.")

    if not story_concept or not story_concept.get("title"):
        raise ValueError("A selected story concept is required.")

    # Existing grouping setting retained to avoid breaking current callers.
    chunk_size = int(pacing.get("questions_per_chunk", 2))
    if chunk_size < 1:
        raise ValueError("questions_per_chunk must be positive.")

    approved_questions = [
        question for question in questions
        if question.get("status") != "rejected"
    ]
    if not approved_questions:
        raise ValueError("No approved questions available.")

    blocks = []
    for index, question in enumerate(approved_questions, start=1):
        question_id = question["id"]
        question_text = question.get("text") or question.get("original")
        if not question_text:
            raise ValueError(f"Question {question_id} has no text.")

        blocks.append({
            "type": "question",
            "question_id": question_id,
            "competency": question["competency"],
            "difficulty": question["difficulty"],
            "text": question_text,
            "sequence": index,
        })

    story_sequence = generate_story_sequence(
        objective=objective,
        story_concept=story_concept,
        questions=approved_questions,
        pacing=pacing,
    )

    # ------------------------------------------------------------
    # AI-ASSISTED ADDITION: Attach story content by question ID.
    # Purpose: Keep dialogue, help, and visuals alongside the exact
    #          approved question; never substitute LLM question text.
    # Directed by: Edenna Chen
    # Generated by: ChatGPT (OpenAI), GPT-6, 2026-11-05
    # ------------------------------------------------------------
    segments_by_id = {
        segment["question_id"]: segment
        for segment in story_sequence["segments"]
    }

    for block in blocks:
        segment = segments_by_id[block["question_id"]]
        block["narrative"] = segment["narrative"]  # Existing preview compatibility.
        block["story_dialogue"] = segment["story_dialogue"]
        block["challenge_transition"] = segment["challenge_transition"]
        block["optional_reminder"] = segment["optional_reminder"]
        block["optional_walkthrough"] = segment["optional_walkthrough"]
        block["visual_prompt"] = segment["visual_prompt"]

    chunks = [
        blocks[i:i + chunk_size]
        for i in range(0, len(blocks), chunk_size)
    ]

    activities = []
    for index, chunk in enumerate(chunks):
        activities.append({
            "type": "activity",
            "activity_number": index + 1,
            "questions": chunk,
            "offer_break_after": (
                bool(pacing.get("offer_breaks", True))
                and index < len(chunks) - 1
            ),
        })

    # ------------------------------------------------------------
    # AI-ASSISTED ADDITION: Expanded lesson response fields.
    # Purpose: Expose the refresher, scene descriptions, optional
    #          finale, and alignment warning to the teacher preview.
    # Directed by: Edenna Chen
    # Generated by: ChatGPT (OpenAI), GPT-6, 2026-11-05
    # ------------------------------------------------------------
    return {
        "lesson_id": uuid.uuid4().hex,
        "student_id": student_id,
        "objective": objective,
        "story": story_concept,
        "pacing": pacing,  # Legacy field; not an adaptive MVP preference.
        "story_complexity": story_sequence["story_complexity"],
        "alignment_warning": story_sequence["alignment_warning"],
        "introduction": story_sequence["introduction"],
        "introduction_visual_prompt": story_sequence["introduction_visual_prompt"],
        "refresher": story_sequence["refresher"],
        "activities": activities,
        "conclusion": story_sequence["conclusion"],
        "conclusion_visual_prompt": story_sequence["conclusion_visual_prompt"],
        "finale_animation": story_sequence["finale_animation"],
        "llm_mode": story_sequence["llm_mode"],
    }
